var u = GameState.get_unit("U_VANGUARD_VETERAN_SQUAD_WITH_JUMP_PACKS_A")
var n := 0
for m in u.models:
	if RulesEngine._get_model_effective_invuln(m, u, int(m.get("invuln", 0))) == 5:
		n += 1
return n

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_real_log_file_path(), FileAccess.READ)
var n := 0
while f != null and not f.eof_reached():
	var l := f.get_line()
	if l.contains("[ERROR"):
		n += 1
		print("[sm11e-m4a] debug-log ERROR: ", l)
return n
